K, W, C = 'Knowledge', 'Wisdom', 'Command'
S, R = 'stated', 'reflection'
def ins(t, b, text): return {'type': t, 'basis': b, 'text': text}
def keeps(t): return {'dir': 'keeps', 'text': t}
def loses(t): return {'dir': 'loses', 'text': t}
def between(t): return {'dir': 'between', 'text': t}
AGREE = between("Hebrew, Greek, Latin and King James agree in substance; only the rendering of the divine name and small turns of phrase differ.")
LEP = between("'Leprosy' in all four columns is the ancient ritual category of skin and surface affliction, not a modern diagnosis; the source keeps the traditional word without clinical claims.")
SPREAD = [loses("Hebrew 'spread' is lost."), keeps("Greek 'shifted' or 'changed' (metapipto)."), between("The Latin and King James have 'spread'.")]
PATCH = [loses("Hebrew 'scaly lesion' (neteq) is lost."), keeps("Greek 'broken patch' (thrausma)."), between("The Latin and King James have 'scall' or a descriptive phrase.")]
PERSIST = [loses("Hebrew 'malignant' (mam'eret) is lost."), keeps("Greek 'persistent' (emmonos)."), between("The Latin and King James have 'persistent' or 'fretting'.")]
P = ['high-priest']

def v(received, explain, shared, k, w, lost, entries=None, cmd=None):
    inst = [ins(K, S, k)]
    if cmd: inst.append(ins(C, S, cmd))
    inst.append(ins(W, R, w))
    return {'received': received, 'explain': explain, 'shared': shared, 'instructions': inst, 'entries': entries if entries is not None else P, 'lost': lost}

